import argparse
import fcntl
import hashlib
import json
import pathlib
import random
import statistics
import subprocess
import time

ROOT = pathlib.Path(__file__).resolve().parents[2]
CACHE = ROOT / '.verify-helper/cache/wm_build'
CACHE.mkdir(parents=True, exist_ok=True)
BASE = '523956f'
source = subprocess.check_output(['git', 'show', BASE + ':data_structure/wavelet_matrix.hpp'], cwd=ROOT, text=True)
quad = subprocess.check_output(['git', 'show', BASE + ':components/quad_bit_vector.hpp'], cwd=ROOT)

def variant(width=11, normalize=False, indexed=False, hist=False, split=False, no_shrink=False):
    s = source
    if normalize:
        s = s.replace('for (int shift = 0, width = std::bit_width(U(lo ^ hi));', 'for (auto &v : order) v.key -= lo;\n\t\t\t\tfor (int shift = 0, width = std::bit_width(U(hi - lo));')
    if width != 11:
        s = s.replace('shift += 11)', f'shift += {width})').replace('std::array<int, 2048>', f'std::array<int, {1 << width}>').replace('& 2047', f'& {(1 << width) - 1}')
    if hist:
        s = s.replace('std::vector<Item> next(n);', f'''std::vector<Item> next(n);
                std::array<std::array<int, {1 << width}>, (sizeof(T) * 8 + {width - 1}) / {width}> histograms{{}};
                for (const auto &v : order)
                    for (int pass = 0; pass < int(histograms.size()); ++pass)
                        ++histograms[pass][(v.key >> (pass * {width})) & {(1 << width) - 1}];''')
        s = s.replace(f'std::array<int, {1 << width}> offsets{{}};\n\t\t\t\t\tfor (const auto &v : order) ++offsets[(v.key >> shift) & {(1 << width) - 1}];', f'auto offsets = histograms[shift / {width}];')
    if indexed:
        s = s.replace('original = compress(a);', 'offsets.clear();\n\t\toriginal = compress(a);\n\t\tbool indexed = !offsets.empty();')
        s = s.replace('offsets.assign(values.size() + 1, 0);', 'if (!indexed) offsets.assign(values.size() + 1, 0);')
        s = s.replace('for (std::uint32_t x : original) ++offsets[x + 1];\n\t\tfor (int i = 0; i < static_cast<int>(values.size()); ++i) offsets[i + 1] += offsets[i];', 'if (!indexed) {\n\t\t\tfor (std::uint32_t x : original) ++offsets[x + 1];\n\t\t\tfor (int i = 0; i < static_cast<int>(values.size()); ++i) offsets[i + 1] += offsets[i];\n\t\t}')
        s = s.replace('positions.resize(n);\n\t\tauto cursor = offsets;\n\t\tfor (int i = 0; i < n; ++i) positions[cursor[original[i]]++] = i;', 'if (!indexed) {\n\t\t\tpositions.resize(n);\n\t\t\tauto cursor = offsets;\n\t\t\tfor (int i = 0; i < n; ++i) positions[cursor[original[i]]++] = i;\n\t\t}')
        old = '''U previous = 0;
                for (const auto &v : order) {
                    if (values.empty() || v.key != previous) values.push_back(a[v.index]);
                    previous = v.key;
                    current[v.index] = static_cast<int>(values.size()) - 1;
                }'''.replace('    ', '\t')
        new = '''U previous = 0;
                positions.resize(n);
                offsets.clear();
                offsets.reserve(n + 1);
                for (int j = 0; j < n; ++j) {
                    const auto &v = order[j];
                    if (values.empty() || v.key != previous) {
                        values.push_back(a[v.index]);
                        offsets.push_back(j);
                    }
                    previous = v.key;
                    current[v.index] = static_cast<int>(values.size()) - 1;
                    positions[j] = v.index;
                }
                offsets.push_back(n);'''.replace('    ', '\t')
        assert old in s
        s = s.replace(old, new)
    if no_shrink:
        s = s.replace('\t\t\t\tvalues.shrink_to_fit();', '').replace('\t\t\tvalues.shrink_to_fit();', '')
    return s

variants = {'baseline': source,
            'norm11': variant(normalize=True),
            'norm8': variant(width=8, normalize=True),
            'norm16': variant(width=16, normalize=True),
            'index11': variant(indexed=True),
            'normindex11': variant(normalize=True, indexed=True),
            'normindex8': variant(width=8, normalize=True, indexed=True),
            'normindex16': variant(width=16, normalize=True, indexed=True),
            'hist11': variant(hist=True),
            'hist8': variant(width=8, hist=True),
            'normindex11_noshrink': variant(normalize=True, indexed=True, no_shrink=True)}

CPP = r'''#include "data_structure/wavelet_matrix.hpp"
#include <chrono>
#include <iostream>
#include <random>
#include <string>
template <class T> int run(int mode, int n, int reps, bool sums) {
    std::mt19937_64 rng(312879013);
    std::vector<T> a(n);
    for (auto &x : a) {
        auto z = rng();
        if (mode == 0 || mode == 6 || mode == 7) x = T(z % 1000000000);
        if (mode == 1) x = T(z % 1000000000) - T(500000000);
        if (mode == 2) x = T(z);
        if (mode == 3) x = T(z % 256);
        if (mode == 4) x = T(std::int64_t(z % 25000) * 6543217 - 12345678901234LL);
        if (mode == 5) x = z & 1 ? std::numeric_limits<T>::min() + T(z % 100) : std::numeric_limits<T>::max() - T(z % 100);
        if (mode == 8) x = T(17);
    }
    if (mode == 6 || mode == 7) std::sort(a.begin(), a.end());
    if (mode == 7) std::reverse(a.begin(), a.end());
    std::vector<T> sorted = a;
    std::sort(sorted.begin(), sorted.end());
    std::uint64_t check = 0;
    double elapsed = 0;
    WaveletMatrix<T> wm;
    for (int rep = 0; rep < reps; ++rep) {
        auto begin = std::chrono::steady_clock::now();
        if (sums) wm = WaveletMatrix<T>(a, true); else wm.build(a);
        elapsed += std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - begin).count();
        for (int i = 0; i < 64; ++i) {
            int k = rng() % n;
            T v = wm.kth_smallest(0, n, k);
            if (v != sorted[k]) return 23;
            check += std::uint64_t(v);
            k = rng() % n;
            if (wm[k] != a[k]) return 24;
            int l = rng() % n, r = rng() % n;
            if (l > r) std::swap(l, r);
            T x = a[rng() % n];
            if (wm.count(l, r, x) != std::count(a.begin() + l, a.begin() + r, x)) return 25;
            if (sums && i == 0) {
                typename WaveletMatrix<T>::sum_type total = 0;
                for (int j = l; j < r; ++j) total += a[j];
                if (wm.range_sum(l, r) != total) return 26;
            }
        }
    }
    std::cout << elapsed / reps << ' ' << check << '\n';
    return 0;
}
int main(int argc, char **argv) {
    int type = std::stoi(argv[1]), mode = std::stoi(argv[2]), n = std::stoi(argv[3]), reps = std::stoi(argv[4]);
    bool sums = argc > 5;
    if (type == 32) return run<std::int32_t>(mode,n,reps,sums);
    if (type == 64) return run<std::int64_t>(mode,n,reps,sums);
    return run<std::uint64_t>(mode,n,reps,sums);
}
'''

parser = argparse.ArgumentParser()
parser.add_argument('--trials', type=int, default=7)
parser.add_argument('--reps', type=int, default=2)
parser.add_argument('--variants', nargs='*', default=list(variants))
parser.add_argument('--sums', action='store_true')
parser.add_argument('--output', default='probe.json')
parser.add_argument('--native', action='store_true')
args = parser.parse_args()

with open('/tmp/cp-wm-opt.lock', 'w') as lock:
    fcntl.flock(lock, fcntl.LOCK_EX)
    for name in args.variants:
        directory = CACHE / name
        (directory / 'data_structure').mkdir(parents=True, exist_ok=True)
        (directory / 'components').mkdir(exist_ok=True)
        (directory / 'data_structure/wavelet_matrix.hpp').write_text(variants[name])
        (directory / 'components/quad_bit_vector.hpp').write_bytes(quad)
        (directory / 'bench.cpp').write_text(CPP)
        command = ['g++', '-std=c++23', '-O2', '-ftrivial-auto-var-init=zero', '-DATCODER', '-DONLINE_JUDGE', '-I' + str(directory), str(directory / 'bench.cpp'), '-o', str(directory / 'bench')]
        if args.native: command.append('-march=native')
        subprocess.run(command, check=True)
    cases = [(200000, t, m) for t in (32,64) for m in range(9)] + [(200000,65,m) for m in (0,2,3,5)]
    raw = {}
    rng = random.Random(20261019)
    for n, typ, mode in cases:
        samples = {v: [] for v in args.variants}
        checksum = None
        for trial in range(args.trials):
            order = args.variants.copy()
            rng.shuffle(order)
            for name in order:
                command = ['taskset', '-c', '2', str(CACHE / name / 'bench'), str(typ), str(mode), str(n), str(args.reps)]
                if args.sums: command += ['sum']
                fields = subprocess.check_output(command, text=True).split()
                if checksum is None: checksum = fields[1]
                assert checksum == fields[1], (name, typ, mode, fields, checksum)
                samples[name].append(float(fields[0]))
        key = f'{n}/{typ}/{mode}'
        raw[key] = {'samples_ms': samples, 'median_ms': {v:statistics.median(s) for v,s in samples.items()}, 'checksum':checksum}
        print(key, raw[key]['median_ms'], flush=True)
        (CACHE / args.output).write_text(json.dumps({'baseline':BASE, 'native':args.native, 'compiler':subprocess.check_output(['g++','--version'], text=True).splitlines()[0], 'flags':'-std=c++23 -O2 -ftrivial-auto-var-init=zero -DATCODER -DONLINE_JUDGE', 'cpu':2, 'trials':args.trials, 'reps':args.reps, 'with_sum':args.sums, 'source_sha256':{v:hashlib.sha256(variants[v].encode()).hexdigest() for v in args.variants}, 'cases':raw}, indent=2))

