import pathlib
path = pathlib.Path(__file__).resolve().with_name('wm_build_probe.py')
text = path.read_text()
start = text.index("parser = argparse.ArgumentParser()")
prefix = text[:start]
suffix = text[start:]
exec(compile(prefix, str(path), 'exec'))

def adaptive_index(packed=False, pointers=False):
    result = variant(indexed=True)
    old = 'for (int shift = 0, width = std::bit_width(U(lo ^ hi)); shift < width; shift += 11) {'
    new = '''int width = std::bit_width(U(lo ^ hi)), span_width = std::bit_width(U(hi - lo));
                if ((width + 10) / 11 > (span_width + 10) / 11) {
                    for (auto &v : order) v.key -= lo;
                    width = span_width;
                }
                for (int shift = 0; shift < width; shift += 11) {'''.replace('    ', '\t')
    assert old in result
    result = result.replace(old, new)
    if packed:
        result = result.replace('struct Item {', 'struct [[gnu::packed]] Item {')
    if pointers:
        old = '''auto offset = middle[d];
        int shift = 2 * (levels - 1 - d);
        for (int i = 0; i < n; ++i) next[offset[(current[i] >> shift) & 3]++] = current[i];'''.replace('    ', '\t')
        new = '''std::array<std::uint32_t *, 4> cursor;
        for (int i = 0; i < 4; ++i) cursor[i] = next.data() + middle[d][i];
        int shift = 2 * (levels - 1 - d);
        for (int i = 0; i < n; ++i) *cursor[(current[i] >> shift) & 3]++ = current[i];'''.replace('    ', '\t')
        assert old in result
        result = result.replace(old, new)
    return result

variants = {'baseline':source, 'index11':variant(indexed=True), 'adaptive':adaptive_index(),
            'adaptive_packed':adaptive_index(packed=True), 'adaptive_ptr':adaptive_index(pointers=True),
            'adaptive_packed_ptr':adaptive_index(packed=True,pointers=True),
            'adaptive_shrink':adaptive_index().replace('values.shrink_to_fit();', 'if (values.capacity() > 2 * values.size()) values.shrink_to_fit();'),
            'adaptive_packed_shrink':adaptive_index(packed=True).replace('values.shrink_to_fit();', 'if (values.capacity() > 2 * values.size()) values.shrink_to_fit();')}
exec(compile(suffix, str(path), 'exec'))

