import fcntl
import hashlib
import json
import pathlib
import random
import statistics
import subprocess

ROOT = pathlib.Path(__file__).resolve().parents[2]
FOLDER = ROOT / '.verify-helper/cache/wm_sum_build'
FOLDER.mkdir(parents=True, exist_ok=True)
source = (ROOT / '.verify-helper/cache/wm_rank_candidate.hpp').read_text()
component = (ROOT / 'components/oct_bit_vector.hpp').read_bytes()
(FOLDER / 'source.hpp').write_text(source)
(FOLDER / 'oct_bit_vector.hpp').write_bytes(component)
start = source.index('\ttemplate <class S>\n\tvoid partition_sum(')
end = source.index('\tusing Route =', start)
old = source[start:end]

scalar_first = old.replace('''\t\tstd::array<int, 2> halves{0, middle[d][4]};
\t\tfor (std::uint32_t x : current) next[halves[(x >> (shift + 2)) & 1]++] = x;''', '''\t\tint zero = 0, one = middle[d][4];
\t\tfor (std::uint32_t x : current) {
\t\t\tbool high = (x >> (shift + 2)) & 1;
\t\t\tint p = high ? one : zero;
\t\t\tone += high;
\t\t\tzero += !high;
\t\t\tnext[p] = x;
\t\t}''')

binary = '''\ttemplate <class S>
\tvoid partition_sum(std::vector<std::vector<S>> &prefix, std::vector<std::uint32_t> &current, std::vector<std::uint32_t> &next, int d) const
\t\trequires supports_sum
\t{
\t\tint shift = 3 * (levels - 1 - d), base = 7 * d + 1;
\t\tfor (int pass = 0; pass < 3; ++pass) {
\t\t\tint groups = 1 << pass;
\t\t\tfor (int group = 0; group < groups; ++group) {
\t\t\t\tint digit = group << (3 - pass);
\t\t\t\tint l = middle[d][digit], m = middle[d][digit + (4 >> pass)];
\t\t\t\tint r = group + 1 == groups ? n : middle[d][digit + (8 >> pass)];
\t\t\t\tint zero = l, one = m;
\t\t\t\tfor (int i = l; i < r; ++i) {
\t\t\t\t\tstd::uint32_t x = current[i];
\t\t\t\t\tbool high = (x >> (shift + 2 - pass)) & 1;
\t\t\t\t\tint p = high ? one : zero;
\t\t\t\t\tone += high;
\t\t\t\t\tzero += !high;
\t\t\t\t\tnext[p] = x;
\t\t\t\t}
\t\t\t\tprefix_sum(prefix[base + groups - 1 + group], next, l, m);
\t\t\t}
\t\t\tcurrent.swap(next);
\t\t}
\t}
'''

skip = binary.replace('''\t\t\tint groups = 1 << pass;
\t\t\tfor (int group''', '''\t\t\tint groups = 1 << pass;
\t\t\tbool unchanged = true;
\t\t\tfor (int group = 0; group < groups; ++group) {
\t\t\t\tint digit = group << (3 - pass);
\t\t\t\tint l = middle[d][digit], m = middle[d][digit + (4 >> pass)];
\t\t\t\tint r = group + 1 == groups ? n : middle[d][digit + (8 >> pass)];
\t\t\t\tunchanged &= l == m || m == r;
\t\t\t}
\t\t\tif (unchanged) {
\t\t\t\tfor (int group = 0; group < groups; ++group) {
\t\t\t\t\tint digit = group << (3 - pass);
\t\t\t\t\tprefix_sum(prefix[base + groups - 1 + group], current, middle[d][digit], middle[d][digit + (4 >> pass)]);
\t\t\t\t}
\t\t\t\tcontinue;
\t\t\t}
\t\t\tfor (int group''')

variants = {'oct_array':source, 'scalar_first':source[:start] + scalar_first + source[end:],
            'binary':source[:start] + binary + source[end:], 'binary_skip':source[:start] + skip + source[end:]}

probe = (ROOT / '.verify-helper/cache/wm_build_probe.py').read_text()
cpp = probe.split("CPP = r'''", 1)[1].split("'''",1)[0]
cpp = cpp.replace('''    std::uint64_t check = 0;''', '''    std::vector<typename WaveletMatrix<T>::sum_type> sums_sorted(n + 1);
    for (int i = 0; i < n; ++i) sums_sorted[i + 1] = sums_sorted[i] + sorted[i];
    std::uint64_t check = 0;''')
cpp = cpp.replace('''            check += std::uint64_t(v);''', '''            check += std::uint64_t(v);
            if (wm.sum_smallest(0, n, k) != sums_sorted[k]) return 27;
            if (wm.sum_largest(0, n, n - k) != sums_sorted[n] - sums_sorted[k]) return 28;''')

flags = ['-std=c++23','-O2','-march=native','-ftrivial-auto-var-init=zero','-DATCODER','-DONLINE_JUDGE']
with open('/tmp/cp-wm-opt.lock','w') as lock:
    fcntl.flock(lock,fcntl.LOCK_EX)
    for name, header in variants.items():
        folder = FOLDER / name
        (folder / 'data_structure').mkdir(parents=True,exist_ok=True)
        (folder / 'components').mkdir(exist_ok=True)
        (folder / 'data_structure/wavelet_matrix.hpp').write_text(header)
        (folder / 'components/oct_bit_vector.hpp').write_bytes(component)
        (folder / 'bench.cpp').write_text(cpp)
        subprocess.run(['g++',*flags,'-I'+str(folder),str(folder/'bench.cpp'),'-o',str(folder/'bench')],check=True)
    raw = {}
    rng = random.Random(20261019)
    cases = [(t,m) for t in (32,64) for m in (0,1,2,3,4,5)]
    for typ, mode in cases:
        times = {v:[] for v in variants}
        checksum = None
        for trial in range(5):
            order = list(variants)
            rng.shuffle(order)
            for name in order:
                fields = subprocess.check_output(['taskset','-c','2',str(FOLDER/name/'bench'),str(typ),str(mode),'200000','2','sum'],text=True).split()
                if checksum is None: checksum = fields[1]
                assert fields[1] == checksum
                times[name].append(float(fields[0]))
        key = f'200000/{typ}/{mode}'
        raw[key] = {'samples_ms':times,'median_ms':{v:statistics.median(s) for v,s in times.items()},'checksum':checksum}
        print(key,raw[key]['median_ms'],flush=True)
        (FOLDER/'results.json').write_text(json.dumps({'flags':flags,'compiler':subprocess.check_output(['g++','--version'],text=True).splitlines()[0], 'cpu':2,'trials':5,'reps':2,'source_sha256':{v:hashlib.sha256(s.encode()).hexdigest() for v,s in variants.items()},'component_sha256':hashlib.sha256(component).hexdigest(),'cases':raw},indent=2))

