		if (r - l <= 4) {
			swap(0, 2), swap(1, 3), swap(1, 2);
		} else {
			swap(4, 5), swap(6, 7);
			swap(0, 2), swap(1, 3), swap(4, 6), swap(5, 7);
			swap(1, 2), swap(5, 6), swap(0, 4), swap(3, 7);
			swap(1, 5), swap(2, 6);
			swap(1, 4), swap(3, 6);
			swap(2, 4), swap(3, 5);
			swap(3, 4);
