	__attribute__((target("avx2,popcnt")))std::pair<int, int> interval_avx2(int l, int r, std::uint32_t x) const {
		for (int d = 0; d < levels; ++d) {
			int digit = (x >> (3 * (levels - 1 - d))) & 7;
