				l = middle[d][digit] + a;
				r = middle[d][digit] + b;
				for (++d; d < levels; ++d) {
					auto step = route_scalar(l, r, Previous ? r - l - 1 : 0, d);
					x = (x << 3) | step.digit;
					l = middle[d][step.digit] + step.a;
					r = middle[d][step.digit] + step.b;
