				} else if (c >= x) best = std::min(best, c);
			}
			if constexpr (Previous) return best ? std::optional<T>(values[best - 1]) : std::nullopt;
			else return best < values.size() ? std::optional<T>(values[best]) : std::nullopt;
		}
