					return current;
				}
				std::vector<Item> next(n);
				for (int shift = 0, width = std::bit_width(U(lo ^ hi)); shift < width; shift += 11) {
					std::array<int, 2048> offsets{};
					for (const auto &v : order) ++offsets[(v.key >> shift) & 2047];
