					for (int &c : offsets) {
						int t = c;
						c = total;
						total += t;
					}
					for (const auto &v : order) next[offsets[(v.key >> shift) & 2047]++] = v;
					order.swap(next);
				}
				values.clear();
				values.reserve(n);
