		for (int i = 0; i < n; ++i) next[offset[(current[i] >> shift) & 7]++] = current[i];
		current.swap(next);
	}
	template <class S>
	void prefix_sum(std::vector<S> &prefix, const std::vector<std::uint32_t> &current, int l, int r) const
