		for (std::uint32_t x : current) next[quarters[(x >> (shift + 1)) & 3]++] = x;
		prefix_sum(prefix[base + 1], next, 0, middle[d][2]);
		prefix_sum(prefix[base + 2], next, middle[d][4], middle[d][6]);
